(function(){"use strict";self.onmessage=async r=>{var c;const{bitmap:e,mult:g,add:d}=r.data;try{const s=new OffscreenCanvas(e.width,e.height),o=s.getContext("2d",{willReadFrequently:!0});o.drawImage(e,0,0);const h=o.getImageData(0,0,s.width,s.height),a=h.data,n=g,m=d;for(let t=0;t<a.length;t+=4)a[t]=Math.min(255,Math.max(0,a[t]*n[0]+m[0])),a[t+1]=Math.min(255,Math.max(0,a[t+1]*n[1]+m[1])),a[t+2]=Math.min(255,Math.max(0,a[t+2]*n[2]+m[2])),a[t+3]=Math.min(255,Math.max(0,a[t+3]*n[3]+m[3]));o.putImageData(h,0,0);const i=s.transferToImageBitmap();self.postMessage({bitmap:i},[i]),(c=e.close)==null||c.call(e)}catch(s){self.postMessage({error:String(s)})}}})();
